triggered := false
if ((#Hallway #MultiButton).multiButton_button1 == "pushed") {
if (triggered == false) {
tmp = (#Hallway #Light).light_currentBrightness + 10
        if (tmp > 100) {
tmp = 100
}
(#Hallway #Light).light_moveToBrightness(tmp, 0)
        triggered = true
}
}
else {
triggered = false
}

